    robust = _median3(_finite_signal(x))
    n = len(robust)
    if n < 3:
        return robust.copy()

    radius = 3
    patches = np.lib.stride_tricks.sliding_window_view(
        np.pad(robust, radius, mode="edge"), 2 * radius + 1
    ).astype(float, copy=True)

    diff_scale = max(_mad_sigma(np.diff(robust)), 1e-9)
    level_limit = 3.0 * diff_scale

    # Identify sustained level changes and assign each sample to a segment.
    jump = np.abs(np.diff(robust))
    candidate = np.flatnonzero(jump > level_limit) + 1
    segment = np.zeros(n, dtype=np.int32)
    segment_id = 0
    for boundary in candidate:
        left = robust[max(0, boundary - 2):boundary]
        right = robust[boundary:min(n, boundary + 2)]
        if len(left) and len(right):
            if abs(float(np.median(right) - np.median(left))) > level_limit:
                segment[boundary:] = segment_id + 1
                segment_id += 1

    local_noise = np.convolve(
        np.abs(np.diff(robust, prepend=robust[0])),
        np.ones(7, dtype=float) / 7.0,
        mode="same",
    )
    global_noise = max(float(np.median(local_noise)), diff_scale)
    alpha = np.clip(
        0.30 + 0.28 * local_noise / max(global_noise, 1e-9),
        0.22,
        0.58,
    )

    graph = [[] for _ in range(n)]
    for i in range(n):
        lo = max(0, i - 48)
        hi = min(n, i + 49)
        candidates = np.arange(lo, hi, dtype=int)
        candidates = candidates[candidates != i]
        if not len(candidates):
